    export default {
        name: 'forecast',
        components: {
            forecastTable
        },
        data() {
            return {
                label: {
                    name: '国' + '\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0' + '库',
                    name1: '辖' + '\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0' + '属',
                    name2: '模' + '\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0' + '型',
                    name3: '科' + '\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0' + '目'
                },
                xiashuOption: [],
                qnumOption: [],
                subjectData: [
                    /* { label: '收入合计', title: '收入合计', pid: '1', key: 'T01', value: 'T01' },
                    { label: '支出合计', title: '支出合计', pid: '2', key: 'T02', value: 'T02' } */
                ],
                esortOption: [],
                sampleOption: [],
                selectedKeys: '',
                SHOW_PARENT,
                radioStyle: {
                    // display: 'block',
                    height: '30px',
                    lineHeight: '30px'
                },
                // 查询条件
                queryParam: {
                    xiashu: '01',
                    qnum: '1',
                    sample: '01',
                    esort: '01',
                    subjectId: sub.split(','),
                    xiashu: "01",
                    statDate: moment('2020-02', 'YYYY-MM'),
                    endDate: moment('2020-07', 'YYYY-MM')
                },
                arr: []
            }
        },
        created() {
            getUserSubjectTreeId({}).then(res => {
                if (res.result === 'success') {
                    this.subjectData = res.rows
                    this.searchQuery();
                }
            })
            //this.searchQuery();
        },
        mounted() {
            /*  var startDate = this.addMonth(new Date(), -4),
             Month = startDate.getMonth() >= 10 ? startDate.getMonth() : '0' + startDate.getMonth();
             this.queryParam.statDate = moment(startDate.getFullYear() + '-' + Month)
             this.dateChange(this.queryParam.statDate); */
        },
        methods: {
            searchQuery() {
                let userInfo = JSON.parse(localStorage.pro__Login_Userinfo).value
                let userId = userInfo.id
                let params = {
                    statDate: this.queryParam.statDate ? this.queryParam.statDate.format('YYYY-MM') : '',
                    endDate: this.queryParam.endDate ? this.queryParam.endDate.format('YYYY-MM') : '',
                    xiashu: this.queryParam.xiashu,
                    qnum: this.queryParam.qnum,
                    esort: this.queryParam.esort,
                    sample: this.queryParam.sample,
                    subjectId: this.queryParam.subjectId.join(','),
                    userId: userId
                }
                gkList(params).then(res => {
                    /* if (res.result === 'success') {
                      let data = res.rows
                      this.initTansCount(data.acc, data.array, data.split0, data.split1, data.split2)
                    } */
                    let data = res
                    this.initTansCount(data.acc, data.array, data.split0, data.split1, data.split2)
                    this.arr = data.factList
                })
                //this.initTansCount(data.acc, data.array, data.split0, data.split1, data.split2)
            },
            showTable() {
                this.$refs.modalForm.visibleModal = true
                this.$refs.modalForm.edit();
            },
            /*导出*/
            handleImports() {
                if (myChart) {
                    this.downloadFile('现金流预测分析.png', myChart.getDataURL({
                        pixelRatio: 2,
                        backgroundColor: '#fff'
                    }));
                }
            },
            //下载
            downloadFile(fileName, content) {
                let aLink = document.createElement('a');
                let blob = this.base64ToBlob(content); //new Blob([content]);

                let evt = document.createEvent("HTMLEvents");
                evt.initEvent("click", true, true);//initEvent 不加后两个参数在FF下会报错  事件类型，是否冒泡，是否阻止浏览器的默认行为
                aLink.download = fileName;
                aLink.href = URL.createObjectURL(blob);

                // aLink.dispatchEvent(evt);
                //aLink.click()
                aLink.dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true, view: window}));//兼容火狐
            },
            //base64转blob
            base64ToBlob(code) {
                let parts = code.split(';base64,');
                let contentType = parts[0].split(':')[1];
                let raw = window.atob(parts[1]);
                let rawLength = raw.length;

                let uInt8Array = new Uint8Array(rawLength);

                for (let i = 0; i < rawLength; ++i) {
                    uInt8Array[i] = raw.charCodeAt(i);
                }
                return new Blob([uInt8Array], {type: contentType});
            },
            addMonth(date, offset) {
                if (date instanceof Date && !isNaN(offset)) {
                    var givenMonth = date.getMonth(),
                        newMonth = givenMonth + offset;
                    date.setMonth(newMonth);
                    return date;
                }
                throw Error('argument type error');
            },
            dateChange(value) {
                var startDate = this.getDate(value) //起始时间
                var startMonth = startDate.month
                var startYear = startDate.year

                var endMonth = startMonth //结束时间
                var endYear = startYear
                var newEndDateStr = '' //拼接好的结束时间字符串
                // if (value == '01') {
                endMonth += 5
                if (endMonth > 12) {
                    endYear++
                    endMonth -= 12
                }
                if (endMonth < 10) {
                    endMonth = '0' + endMonth
                }
                //whichChecked = '01'
                if (endMonth.toString().length == 1) {
                    newEndDateStr = endYear + '-' + '0' + endMonth
                } else {
                    newEndDateStr = endYear + '-' + endMonth
                }

                this.queryParam.endDate = moment(newEndDateStr)
            },
            getDate(dateStr) {
                var date = ''
                if (dateStr) {
                    date = new Date(dateStr)
                } else {
                    date = new Date()
                }
                var year = date.getFullYear()
                var month = date.getMonth()
                return {
                    year: year,
                    month: month + 1
                }
            },
            initTansCount(acc, array, split0, split1, split2) {
                myChart = echarts.init(document.getElementById('tansMoney'));
                let oThis = this;
                let option = {
                    tooltip: {
                        trigger: 'axis',
                        formatter: function (params) {
                            var res = '<div><p>月份：' + params[0].name + '</p></div>'
                            for (var i = 0; i < params.length; i++) {
                                if (params[i].seriesName == '误差比') {
                                    res +=
                                        '<p>' + params[i].seriesName + ':' + oThis.formatNum((params[i].data * 100).toFixed(2).toString()) + '%</p>'
                                } else {
                                    res += '<p>' + params[i].seriesName + ':' + oThis.formatNum(params[i].data.toString()) + '</p>'
                                }
                            }

                            // res+='<p>'+params[3].seriesName+':'+(params[3].data*100).toFixed(2)+'%</p>'
                            return res
                        }
                    },
                    legend: {
                        data: [
                            {name: '实际值'},
                            {name: '预测值'},
                            {name: '误差值'},
                            {name: '误差比'}
                        ]
                    },
                    grid: {
                        containLabel: true
                    },
                    xAxis: [
                        {
                            type: 'category',
                            data: eval(acc)
                        }
                    ],
                    yAxis: [
                        {
                            type: 'value',
                            scale: true,
                            name: '金额',

                            axisLabel: {
                                formatter: '{value}'
                            }
                        },
                        {
                            type: 'value',
                            scale: true,
                            name: '误差比（%）'
                        }
                    ],
                    series: [
                        {
                            name: '实际值',
                            type: 'line',
                            data: eval(array)
                        },
                        {
                            name: '预测值',
                            type: 'line',
                            data: eval(split0)
                        },
                        // {
                        //     name: '误差值',
                        //     type: 'line',
                        //     data: eval(split1)
                        // }
                        // ,
                        {
                            name: '误差比',
                            type: 'line',
                            yAxisIndex: 1,
                            lineStyle: {
                                type: 'dashed'
                            },
                            data: eval(split2)
                        }
                    ]
                }

                myChart.setOption(option)
            },
            formatNum(str) {
                var newStr = ''
                var count = 0
                if (str.indexOf('.') == -1) {
                    for (var i = str.length - 1; i >= 0; i--) {
                        if (count % 3 == 0 && count != 0) {
                            newStr = str.charAt(i) + ',' + newStr
                        } else {
                            newStr = str.charAt(i) + newStr
                        }
                        count++
                    }
                    str = newStr + '.00' //自动补小数点后两位
                } else {
                    for (var i = str.indexOf('.') - 1; i >= 0; i--) {
                        if (count % 3 == 0 && count != 0) {
                            newStr = str.charAt(i) + ',' + newStr
                        } else {
                            newStr = str.charAt(i) + newStr //逐个字符相接起来
                        }
                        count++
                    }
                    str = newStr + (str + '00').substr((str + '00').indexOf('.'), 3)
                }
                return str
            }
        }
    }
</script>

